export const GAS_R=8.314462618,FARADAY=96485.33212;
export function chemistry12(m,x){switch(m){case 0:return{value:100*x,lowering:100*(1-x)};case 1:return{value:x*1000*GAS_R*300/1000};case 2:return{value:1.86*x,freezing:-1.86*x};case 3:return{value:1.1-GAS_R*298/(2*FARADAY)*Math.log(x)};case 4:return{value:x*600*63.546/(2*FARADAY),charge:x*600};case 5:return{value:1000*x/.1};case 6:return{value:Math.exp(-.02*x),halfLife:Math.log(2)/.02};case 7:return{value:1-.02*x};case 8:return{value:1e10*Math.exp(-50000/(GAS_R*x))};case 9:return{value:Math.sqrt(x*(x+2))};case 10:return{value:x};case 11:return{value:Math.min(x,14-x)};case 12:return{value:[2,4,4,6][x]};case 13:return{value:x,lower:-.4*x,upper:.6*x,barycentre:3*(-.4*x)+2*(.6*x)};case 14:return{value:x===0?90:180};case 15:case 16:case 17:case 18:case 20:case 21:case 22:case 26:return{value:x};case 19:return{value:[16,10,15.7][x]};case 23:return{value:[4.76,2.86,.7][x],ka:10**(-[4.76,2.86,.7][x])};case 24:return{value:[1.8e-5,4.4e-4,4.3e-10][x],pkb:-Math.log10([1.8e-5,4.4e-4,4.3e-10][x])};case 25:return{value:x,cold:x<=278};case 27:return{value:x===2?0:1};case 28:return{value:x-1,water:x-1};case 29:return{value:x<2?2:3};default:throw Error('Unknown chemistry12 mode '+m)}}
